shared_before.runtime:
import { deepEqual, equal, throws } from "node:assert/strict";
import {
  copyJsonValue,
  err,
  isErr,
  isOk,
  messageDescriptor,
  messageKey,
  ok,
} from "../../../../src/shared/index";
import { diagnosticDescriptor } from "../../../../src/diagnostics/index";

// Time and UUID unit cases now live in shared/time/unit/ and shared/uuid/unit/.
const descriptor = messageDescriptor({
  code: "VALIDATION_REQUIRED",
  defaultMessage: "Field is required.",
  messageKey: "validation.required",
  params: { field: "email" },
});
equal(descriptor.messageKey, messageKey("validation.required"));
equal(descriptor.params?.field, "email");

const copiedJson = copyJsonValue({
  id: "deal-123",
  score: 12,
  flags: [true, false],
  nested: { value: null },
});
deepEqual(copiedJson, {
  id: "deal-123",
  score: 12,
  flags: [true, false],
  nested: { value: null },
});
throws(() => copyJsonValue(Number.NaN, "test JSON value"), /finite numbers/);
throws(() => copyJsonValue(Number.POSITIVE_INFINITY, "test JSON value"), /finite numbers/);
throws(() => copyJsonValue(new Date() as never, "test JSON value"), /plain objects/);

const success = ok({ enabled: true });
equal(isOk(success), true);
if (!isOk(success)) {
  throw new Error("Expected result to be ok.");
}
equal(success.value.enabled, true);

const failure = err({ code: "TEST_FAILURE", defaultMessage: "Expected failure." });
equal(isErr(failure), true);
if (!isErr(failure)) {
  throw new Error("Expected result to be err.");
}
equal(failure.error.code, "TEST_FAILURE");
equal(failure.error.defaultMessage, "Expected failure.");

const diagnosticFailure = err({
  code: "CSV_IMPORT_INVALID_ROW",
  defaultMessage: "CSV import row is invalid.",
  diagnostic: diagnosticDescriptor({
    failureKind: "user_input",
    failureSource: "user",
    severity: "warning",
    recovery: "user_correctable",
    action: "ask_user",
  }),
});
equal(isErr(diagnosticFailure), true);
if (!isErr(diagnosticFailure)) {
  throw new Error("Expected diagnostic failure to be err.");
}
equal(diagnosticFailure.error.diagnostic?.failureKind, "user_input");
equal(diagnosticFailure.error.diagnostic?.userCorrectable, true);


console.log("packages/core shared runtime test passed.");

shared_before.types:
import {
  correlationId,
  causationId,
  entityId,
  err,
  isErr,
  isOk,
  copyJsonValue,
  messageDescriptor,
  messageKey,
  ok,
  type CorrelationId,
  type CausationId,
  type EntityId,
  type JsonValue,
  type MessageDescriptor,
  type MessageKey,
  type Result,
} from "../../../../src/shared/index";
import { diagnosticDescriptor } from "../../../../src/diagnostics/index";
import type { CoreError } from "../../../../src/shared/index";

type TenantId = EntityId<"TenantId">;
type PrincipalId = EntityId<"PrincipalId">;

const tenantId = entityId<"TenantId">("tenant-123");
const principalId = entityId<"PrincipalId">("principal-456");
const requestId = correlationId("request-789");
const triggerId = causationId("event-456");

const acceptedTenantId: TenantId = tenantId;
const acceptedPrincipalId: PrincipalId = principalId;
const acceptedCorrelationId: CorrelationId = requestId;
const acceptedCausationId: CausationId = triggerId;
const acceptedMessageKey: MessageKey = messageKey("validation.required");
const acceptedMessageDescriptor: MessageDescriptor = messageDescriptor({
  code: "VALIDATION_REQUIRED",
  defaultMessage: "Field is required.",
  messageKey: acceptedMessageKey,
  params: { field: "email", minimum: 1, required: true, optional: null },
});
const acceptedJsonValue: JsonValue = {
  id: "deal-123",
  flags: [true, false],
  nested: { value: null },
};

void acceptedTenantId;
void acceptedPrincipalId;
void acceptedCorrelationId;
void acceptedCausationId;
void acceptedMessageKey;
void acceptedMessageDescriptor;
void copyJsonValue(acceptedJsonValue);

// @ts-expect-error JSON values must stay plain and serializable.
const rejectedJsonValue: JsonValue = new Date();
void rejectedJsonValue;

// @ts-expect-error message descriptors must keep params JSON-primitive and localization-friendly.
messageDescriptor({ code: "BAD_PARAM", defaultMessage: "Bad param.", params: { nested: { value: "nope" } } });

// @ts-expect-error message descriptors require fallback/debug text for untranslated contexts.
messageDescriptor({ code: "MISSING_DEFAULT_MESSAGE" });

// @ts-expect-error branded IDs with different names must not be interchangeable.
const rejectedTenantId: TenantId = principalId;
void rejectedTenantId;

// @ts-expect-error correlation IDs must not be accepted as entity IDs.
const rejectedEntityId: EntityId<"TenantId"> = requestId;
void rejectedEntityId;

// Time and UUID type-level cases now live in their shared/<theme>/type-level/ groups.

const success: Result<string> = ok("ready");
const failure: Result<string> = err({ code: "TEST_FAILURE", defaultMessage: "Expected failure." });
const diagnosticFailure: CoreError = {
  code: "CSV_IMPORT_INVALID_ROW",
  defaultMessage: "CSV import row is invalid.",
  diagnostic: diagnosticDescriptor({
    failureKind: "user_input",
    failureSource: "user",
    severity: "warning",
    recovery: "user_correctable",
    action: "ask_user",
  }),
};

if (isOk(success)) {
  const value: string = success.value;
  void value;
}

if (isErr(failure)) {
  const code: string = failure.error.code;
  void code;
}

void diagnosticFailure;

runner_regression_before:
import { deepEqual, equal, match, notEqual } from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";

const runner = resolve("packages/core/tests/run-runtime-tests.mjs");

function fixture(check: (root: string, source: (name: string, compiled?: string) => void, compiled: (name: string, body: string) => void) => void): void {
  const root = mkdtempSync(join(tmpdir(), "core-test-runner-"));
  const sourceRoot = join(root, "packages/core/tests");
  const compiledRoot = join(root, ".cache/packages-core-runtime/tests");
  const write = (file: string, body: string) => {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, body);
  };
  const compiled = (name: string, body: string) => write(join(compiledRoot, name), body);
  const source = (name: string, body?: string) => {
    write(join(sourceRoot, name), "export {};\n");
    if (body !== undefined) compiled(name.replace(/\.ts$/, ".js"), body);
  };
  try {
    mkdirSync(sourceRoot, { recursive: true });
    mkdirSync(compiledRoot, { recursive: true });
    check(root, source, compiled);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}

function run(root: string) {
  return spawnSync(process.execPath, [runner], { cwd: root, encoding: "utf8", timeout: 10_000 });
}

fixture((root, source, compiled) => {
  source("z-runtime.test.ts", 'console.log("last");');
  source("shared/time/unit/first-runtime.test.ts", 'console.log("nested");');
  source("first-runtime.test.ts", 'console.log("flat");');
  source("shared/time/type-level/time-types.test.ts", "process.exit(91);");
  compiled("stale-runtime.test.js", "process.exit(92);");
  compiled("shared/time/unit/retired-runtime.test.js", "process.exit(93);");

  const actual = run(root);

  equal(actual.status, 0, "flat and nested source-backed cases execute successfully");
  deepEqual(actual.stdout.trim().split(/\r?\n/), ["flat", "nested", "last"],
    "discovery is deterministic, runs each case once, handles duplicate basenames and excludes type-only/stale output");
});

fixture((root, source) => {
  source("first-runtime.test.ts", 'console.log("must not run");');
  source("shared/time/unit/missing-runtime.test.ts");

  const actual = run(root);

  notEqual(actual.status, 0, "missing nested compilation fails the runner");
  match(actual.stderr, /Compiled Core runtime test unavailable: .*missing-runtime\.test\.js/);
  equal(actual.stdout, "", "missing compilation is detected before other cases execute");
});

fixture((root, source) => {
  source("shared/time/unit/a-runtime.test.ts", 'console.log("failed case"); process.exit(7);');
  source("z-runtime.test.ts", 'console.log("must not run");');

  const actual = run(root);

  equal(actual.status, 7, "a nested child failure retains its exact nonzero status");
  equal(actual.stdout.trim(), "failed case", "the runner stops after a failed case");
});

fixture((root, source, compiled) => {
  source("shared/time/type-level/time-types.test.ts", "process.exit(91);");
  compiled("retired-runtime.test.js", "process.exit(92);");

  const actual = run(root);

  notEqual(actual.status, 0, "type-only and stale output cannot conceal zero runtime cases");
  match(actual.stderr, /No packages\/core runtime tests found/);
  equal(actual.stdout, "", "no compiled-only file executes");
});

fixture((root, source) => {
  source("actual-runtime.test.ts", 'console.log("must not run");');
  symlinkSync("actual-runtime.test.ts", join(root, "packages/core/tests/alias-runtime.test.ts"));

  const actual = run(root);

  notEqual(actual.status, 0, "ambiguous symlink discovery fails rather than silently omitting or duplicating a case");
  match(actual.stderr, /Core test discovery does not support symlinks/);
  equal(actual.stdout, "", "invalid discovery fails before case execution");
});

console.log("packages/core test-runner unit regressions passed.");
